import assert from 'node:assert/strict';
import SuperJSON from './dist/index.js';
const s = new SuperJSON({errorStack:{mode:'frames',includeCauses:'deep',sanitizeMessage:true}}); s.allowErrorProps('stackFrames');
const e = new Error('hello', {cause:new Error('visit https://example.com')}); e.stack='Error: hello\n    at f (/tmp/file.js:1:2)';
const r=s.serialize(e); assert.equal(r.meta.values[0],'Error/frames'); assert.equal(r.json.stackFrames[0].raw,'Error: hello'); assert.equal(r.json.cause.message,'visit [redacted]');
for (const value of [e,[e],new Map([['x',e]]),new Set([e])]) { const out=s.parse(s.stringify(value)); const v=out instanceof Map?out.get('x'):out instanceof Set?[...out][0]:Array.isArray(out)?out[0]:out; assert.equal(v.stackFrames[0].raw,'Error: hello'); assert(v.cause instanceof Error); }
console.log('Frame and cause checks passed');
EOF
